mapper.select:
SELECT * FROM ( SELECT ROWNUM AS RNUM, A.* FROM ( SELECT X.BUYER AS BUYER, DECODE (SUBSTR (X.BUYER, 7, 1), 'G', (SELECT COMORG_NAME FROM BYCAORGL WHERE COMORG_CODE = X.BUYER), (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = X.BUYER)) AS BUYER_NAME, X.CNT AS CNT FROM ICOMCQDT_BYIT_CNT_MV X WHERE AGENT = #{com_code}
AND DECODE (SUBSTR (X.BUYER, 7, 1), 'G', (SELECT COMORG_NAME FROM BYCAORGL WHERE COMORG_CODE = X.BUYER), (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = X.BUYER)) LIKE '%'||#{keyword}||'%'
ORDER BY BUYER_NAME ) A
WHERE ROWNUM <= #{endRow}
)
WHERE RNUM > #{startRow}
